    flare: { name: 'Poussee', summary: 'Periode d aggravation ou pic de symptomes utile a suivre comme schema plutot que de compter sur la memoire.', definition: 'La page Poussee de Zebra se concentre sur ce qui a change, combien de temps cela a dure, ce qui se passait autour et l impact sur la fonction ou les questions de suivi.' },
    'baseline-symptoms': { name: 'Symptomes de reference', summary: 'Page de workflow pour noter ce qui est normal pour vous avant qu une poussee, un changement de medicament ou un rendez-vous rende les details plus difficiles a rappeler.', definition: 'Symptomes de reference separe dans Zebra votre schema habituel de ce qui a change, empire ou commence a arriver plus souvent avant un rendez-vous.', practicalUse: { title: 'Quoi noter en premier', body: 'Une reference est plus utile quand elle est simple et precise. Elle n a pas besoin d expliquer pourquoi les symptomes arrivent; elle doit seulement capturer a quoi ressemble une semaine normale avant un changement.', items: ['Symptomes habituellement presents meme un jour ordinaire', 'Ce qui compte comme pire que d habitude pour douleur, vertiges, fatigue, brouillard mental ou symptomes cardiaques', 'Ce que vous pouvez faire d habitude, comme rester debout, marcher, cuisiner, travailler ou sortir', 'Contexte habituel de medicaments, sel, eau, sommeil, chaleur ou activite'] }, appointmentUse: { title: 'Comment cela aide avant un rendez-vous', body: 'La valeur en consultation est le contraste. Au lieu d expliquer tout le mois de memoire, vous pouvez montrer ce qui etait typique, ce qui a change et quand cela a commence.', items: ['L utiliser avant un nouveau medicament ou changement de dose', 'L utiliser apres une poussee pour comparer la phase plus difficile', 'L utiliser avant un rendez-vous si les symptomes bougent depuis plusieurs semaines'] } },
